describe('Form Submission Confirmation Email', () => {
  beforeEach(() => {
    cy.visit('/contact-form');
  });

  it('should send confirmation email after successful form submission', () => {
    // Intercept the API call to submit the form
    cy.intercept('POST', '/api/form/submit').as('formSubmission');

    // Fill in form fields
    cy.get('[data-testid="name-input"]').type('John Doe');
    cy.get('[data-testid="email-input"]').type('john.doe@example.com');
    cy.get('[data-testid="subject-input"]').type('Inquiry about service');
    cy.get('[data-testid="message-textarea"]').type('I would like to learn more about your services.');

    // Submit the form
    cy.get('[data-testid="submit-button"]').click();

    // Wait for the API call
    cy.wait('@formSubmission');

    // Verify success message is displayed
    cy.get('[data-testid="success-message"]').should('be.visible').should('contain', 'Form submitted successfully');

    // Verify confirmation email notification
    cy.get('[data-testid="confirmation-email-notification"]').should('be.visible').should('contain', 'Confirmation email sent');

    // Verify form is cleared
    cy.get('[data-testid="name-input"]').should('have.value', '');
    cy.get('[data-testid="email-input"]').should('have.value', '');
  });

  it('should handle form submission with invalid email format and display error', () => {
    // Intercept the API call
    cy.intercept('POST', '/api/form/submit').as('formSubmission');

    // Fill in form with invalid email
    cy.get('[data-testid="name-input"]').type('Jane Doe');
    cy.get('[data-testid="email-input"]').type('invalid-email-format');
    cy.get('[data-testid="subject-input"]').type('Test');
    cy.get('[data-testid="message-textarea"]').type('This is a test message.');

    // Submit the form
    cy.get('[data-testid="submit-button"]').click();

    // Wait for the API call
    cy.wait('@formSubmission');

    // Verify error message is displayed
    cy.get('[data-testid="error-message"]').should('be.visible').should('contain', 'Please enter a valid email address');

    // Verify success message is NOT displayed
    cy.get('[data-testid="success-message"]').should('not.exist');

    // Verify confirmation email notification is NOT displayed
    cy.get('[data-testid="confirmation-email-notification"]').should('not.exist');

    // Verify form fields are still populated
    cy.get('[data-testid="name-input"]').should('have.value', 'Jane Doe');
    cy.get('[data-testid="email-input"]').should('have.value', 'invalid-email-format');
  });
});
